@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbGraphPathRestrictionTest {

	private static final String NS = "urn:graph-path-restriction:";
	private static final int NODES = 32;
	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@TempDir
	File directory;

	@ParameterizedTest(name = "{0}: {1} {2}")
	@MethodSource("restrictedPaths")
	void outerValuesRestrictPathsWithoutNativeEvaluation(GraphJoinOptimization mode, String operator,
			Direction direction) {
		SailRepository repository = repository(mode);
		try (var connection = repository.getConnection()) {
			loadChains(connection);
			String values = switch (direction) {
			case FORWARD -> "VALUES ?s { :n0 }";
			case REVERSE -> "VALUES ?o { :n" + (NODES - 1) + " }";
			case BOTH -> "VALUES (?s ?o) { (:n0 :n" + (NODES - 1) + ") }";
			};
			TupleQuery query = query(connection, operator, values);
			assertThat(rows(query)).containsExactlyInAnyOrderElementsOf(expected(operator, direction));

			GenericPlanNode plan = query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			assertThat(actualMetric(plan, "graphRestrictionPathProbes"))
					.as("the ordinary LMDB evaluator must restrict the selected path by its endpoint")
					.isGreaterThan(0L);
			assertThat(actualMetric(plan, "graphRestrictionReplayRows"))
					.as("a selective path must not enumerate and spool every reachable pair")
					.isZero();
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@EnumSource(value = GraphJoinOptimization.class, names = { "AUTO", "REQUIRE_RESTRICTED" })
	void optionalPathPreservesDuplicateOuterValues(GraphJoinOptimization mode) {
		SailRepository repository = repository(mode);
		try (var connection = repository.getConnection()) {
			loadChains(connection);
			TupleQuery query = query(connection, "?", "VALUES ?s { :n0 :n0 }");
			assertThat(rows(query)).containsExactlyInAnyOrder(row(0, 0), row(0, 1), row(0, 0), row(0, 1));

			GenericPlanNode plan = query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			assertThat(actualMetric(plan, "graphRestrictionPathProbes"))
					.as("the parser's DISTINCT path region must retain a restriction adapter")
					.isGreaterThan(0L);
			assertThat(actualMetric(plan, "graphRestrictionReplayRows")).isZero();
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "*", "+" })
	void absentOuterEndpointDoesNotCreateAPathInTheSelectedGraph(String operator) {
		SailRepository repository = repository(GraphJoinOptimization.AUTO);
		try (var connection = repository.getConnection()) {
			loadChains(connection);
			TupleQuery query = query(connection, operator, "VALUES ?s { :absent }");
			assertThat(rows(query)).isEmpty();
		} finally {
			repository.shutDown();
		}
	}

	private static Stream<Arguments> restrictedPaths() {
		return Stream.of(GraphJoinOptimization.AUTO, GraphJoinOptimization.REQUIRE_RESTRICTED)
				.flatMap(mode -> Stream.of("*", "+")
						.flatMap(operator -> Stream.of(Direction.values())
								.map(direction -> Arguments.of(mode, operator, direction))));
	}

	private SailRepository repository(GraphJoinOptimization mode) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setNativeEvaluationEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setDirectAdjacencyMode(DirectAdjacencyMode.DISABLED)
				.setValueOverlayEnabled(false)
				.setSketchEstimatorEnabled(false);
		LmdbStore store = new LmdbStore(directory, config);
		store.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT.withGraphJoinOptimization(mode));
		// Use LMDB's real default factory: a manually installed generic factory hides this regression.
		assertThat(store.getEvaluationStrategyFactory()).isInstanceOf(LmdbDefaultEvaluationStrategyFactory.class);
		return new SailRepository(store);
	}

	private static void loadChains(RepositoryConnection connection) {
		connection.begin();
		for (String chain : List.of("n", "unrelated")) {
			for (int i = 1; i < NODES; i++) {
				connection.add(VF.createIRI(NS + chain + (i - 1)), VF.createIRI(NS + "p"),
						VF.createIRI(NS + chain + i), VF.createIRI(NS + "graph"));
			}
		}
		connection.commit();
	}

	private static TupleQuery query(RepositoryConnection connection, String operator, String values) {
		TupleQuery query = connection.prepareTupleQuery("PREFIX : <" + NS + "> "
				+ "SELECT ?s ?o FROM NAMED :graph WHERE { " + values + " GRAPH :graph { ?s :p" + operator
				+ " ?o } }");
		query.setIncludeInferred(false);
		return query;
	}

	private static List<BindingSet> expected(String operator, Direction direction) {
		List<BindingSet> expected = new ArrayList<>();
		if (direction == Direction.BOTH) {
			expected.add(row(0, NODES - 1));
		} else {
			for (int node = 0; node < NODES; node++) {
				int subject = direction == Direction.FORWARD ? 0 : node;
				int object = direction == Direction.FORWARD ? node : NODES - 1;
				if (operator.equals("*") || subject != object) {
					expected.add(row(subject, object));
				}
			}
		}
		return expected;
	}

	private static BindingSet row(int subject, int object) {
		QueryBindingSet row = new QueryBindingSet();
		row.addBinding("s", VF.createIRI(NS + "n" + subject));
		row.addBinding("o", VF.createIRI(NS + "n" + object));
		return row;
	}

	private static List<BindingSet> rows(TupleQuery query) {
		List<BindingSet> rows = new ArrayList<>();
		try (var result = query.evaluate()) {
			result.forEachRemaining(rows::add);
		}
		return rows;
	}

	private static long actualMetric(GenericPlanNode node, String name) {
		Long own = node.getLongMetricActual(name);
		long total = own == null ? 0 : own;
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				total += actualMetric(child, name);
			}
		}
		return total;
	}

	private enum Direction {
		FORWARD,
		REVERSE,
		BOTH
	}
}
